function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('script[type="application/ld+json"]').each((_, el) => {
    let data;
    try {
      data = JSON.parse($(el).text());
    } catch (_) {
      return;
    }

    // Support both a single Menu object or a graph containing it
    const getMenu = obj => {
      if (!obj) return null;
      if (obj['@type'] === 'Menu') return obj;
      if (Array.isArray(obj)) {
        for const o of obj) {
          if (o['@type'] === 'Menu') return o;
        }
      }
      if (obj['@graph']) {
        for const o of obj['@graph']) {
          if (o['@type'] === 'Menu') return o;
        }
      }
      return null;
    };

    const menu = getMenu(data);
    if (!menu) return;

    const sections = menu.hasMenuSection || [];
    for (const sec of sections) {
      const sectionName = sec.name ? cleanText(sec.name) : null;
      const menuItems = sec.hasMenuItem || [];
      for (const it of menuItems) {
        const name = it.name ? cleanText(it.name) : null;
        if (!name) continue;
        const description = it.description ? cleanText(it.description) : null;
        let price = null;
        if (it.offers) {
          const offer = it.offers;
          // Some schemas wrap price in an array or nested object; handle common shapes
          let priceVal = null;
          if (Array.isArray(offer)) {
            // take first offer that looks valid
            for const o of offer) {
              if (o && o.price !== undefined) { priceVal = o.price; break; }
            }
          } else {
            priceVal = offer.price !== undefined ? offer.price : null;
          }
          if (priceVal !== null) price = parsePrice(String(priceVal));
        }
        const key = `${sectionName}||${name}||${price}`;
        if (!seen.has(key)) {
          seen.add(key);
          items.push({ section: sectionName, name, description, price });
        }
      }
    }
  });

  return items;
}
